// NEW proposal only; no main import until explicit root selection.
export function inReturnRegion(foot,rows){return Array.isArray(foot)&&foot.length===2&&foot.every(Number.isInteger)&&rows.some(([y,a,b])=>foot[1]===y&&foot[0]>=a&&foot[0]<b)}
export function mayReturn({scene,facing,foot,freshPress,pinsVerified,safe},rows){return scene==='jungle-exterior-r7'&&facing==='down'&&freshPress===true&&pinsVerified===true&&inReturnRegion(foot,rows)&&safe(foot)}

