export class ReturnGuard{constructor(){this.reset()}reset(){this.released=false;this.left=false;this.held=true}release(){this.released=true;this.held=false}observe(scene,foot){if(scene!=='jungle-exterior-r7'||!inReturnRegion(foot,RETURN_ROWS))this.left=true}get armed(){return this.released&&this.left&&!this.held}press(){if(!this.armed)return false;this.held=true;return true}}
